/** Shortest distance from Belo Horizonte to the border, in artwork pixels (how far the zoom must go to fill a screen). */
export const MINAS_BH_CLEARANCE = 32.99;

/**
 * SVG path of the map with each artwork pixel at `scale` points, the artwork's top left at (`left`, `top`), and the
 * whole map zoomed by `zoom` around (`cx`, `cy`). Runs on the UI thread too (Reanimated worklet).
 */
export function minasPath(scale: number, left: number, top: number, zoom = 1, cx = 0, cy = 0): string {
  'worklet';
  const n = MINAS_POINTS.length / 2;
  const X = (i: number) => cx + (left + MINAS_POINTS[2 * i] * scale - cx) * zoom;
  const Y = (i: number) => cy + (top + MINAS_POINTS[2 * i + 1] * scale - cy) * zoom;
  let d = `M${((X(n - 1) + X(0)) / 2).toFixed(1)} ${((Y(n - 1) + Y(0)) / 2).toFixed(1)}`;
  for (let i = 0; i < n; i++) {
    const j = (i + 1) % n;
    d += `Q${X(i).toFixed(1)} ${Y(i).toFixed(1)} ${((X(i) + X(j)) / 2).toFixed(1)} ${((Y(i) + Y(j)) / 2).toFixed(1)}`;
  }
  return d + 'Z';
}
